use clap::Parser;
use regex::Regex;
use scraper::{Html, Selector};
use std::collections::HashMap;
use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use url::Url;

#[derive(Parser, Debug)]
#[command(
    name = "html2markdown",
    about = "Convert HTML to Markdown. Even works with entire websites!",
    version = "html2markdown\n\nGitVersion:  dev\nGitCommit:   none\nBuildDate:   unknown"
)]
struct Args {
    /// Input file, directory, or glob pattern (instead of stdin)
    #[arg(long)]
    input: Option<String>,

    /// Output file or directory (instead of stdout)
    #[arg(long)]
    output: Option<String>,

    /// Replace existing files
    #[arg(long)]
    output_overwrite: bool,

    /// Show version
    #[arg(short, long)]
    version: bool,

    /// The url of the web page, used to convert relative links to absolute links
    #[arg(long)]
    domain: Option<String>,

    /// CSS query selector to exclude parts of the input
    #[arg(long)]
    exclude_selector: Option<String>,

    /// CSS query selector to only include parts of the input
    #[arg(long)]
    include_selector: Option<String>,

    /// Make bold text. Should <strong> be indicated by two asterisks or two underscores?
    #[arg(long, default_value = "**")]
    opt_strong_delimiter: String,

    /// Enable the strikethrough plugin
    #[arg(long)]
    plugin_strikethrough: bool,

    /// Enable the table plugin
    #[arg(long)]
    plugin_table: bool,

    /// [for --plugin-table] whether cells in the tables should include extra padding for visual continuity
    #[arg(long, default_value = "aligned")]
    opt_table_cell_padding_behavior: String,

    /// [for --plugin-table] first row should be treated as a header
    #[arg(long)]
    opt_table_header_promotion: bool,

    /// [for --plugin-table] how tables containing newlines should be handled
    #[arg(long, default_value = "preserve")]
    opt_table_newline_behavior: String,

    /// [for --plugin-table] whether tables with role="presentation" should be converted
    #[arg(long)]
    opt_table_presentation_tables: bool,

    /// [for --plugin-table] how colspan/rowspan should be rendered
    #[arg(long, default_value = "empty")]
    opt_table_span_cell_behavior: String,

    /// [for --plugin-table] omit empty rows from the output
    #[arg(long)]
    opt_table_skip_empty_rows: bool,
}

struct Config {
    strong_delimiter: String,
    plugin_strikethrough: bool,
    plugin_table: bool,
    domain: Option<String>,
    include_selector: Option<Selector>,
    exclude_selector: Option<Selector>,
    table_cell_padding_behavior: String,
    table_header_promotion: bool,
    table_newline_behavior: String,
    table_presentation_tables: bool,
    table_span_cell_behavior: String,
    table_skip_empty_rows: bool,
}

impl Config {
    fn from_args(args: &Args) -> Self {
        let include_selector = args
            .include_selector
            .as_ref()
            .and_then(|s| Selector::parse(s).ok());
        let exclude_selector = args
            .exclude_selector
            .as_ref()
            .and_then(|s| Selector::parse(s).ok());

        Config {
            strong_delimiter: args.opt_strong_delimiter.clone(),
            plugin_strikethrough: args.plugin_strikethrough,
            plugin_table: args.plugin_table,
            domain: args.domain.clone(),
            include_selector,
            exclude_selector,
            table_cell_padding_behavior: args.opt_table_cell_padding_behavior.clone(),
            table_header_promotion: args.opt_table_header_promotion,
            table_newline_behavior: args.opt_table_newline_behavior.clone(),
            table_presentation_tables: args.opt_table_presentation_tables,
            table_span_cell_behavior: args.opt_table_span_cell_behavior.clone(),
            table_skip_empty_rows: args.opt_table_skip_empty_rows,
        }
    }
}

fn main() {
    let args = Args::parse();

    if args.version {
        Args::command().render_version();
        return;
    }

    let config = Config::from_args(&args);

    if let Some(input_path) = &args.input {
        let output_path = args.output.as_ref();
        process_input(input_path, output_path, args.output_overwrite, &config);
    } else {
        let mut input = String::new();
        io::stdin()
            .read_to_string(&mut input)
            .expect("Failed to read from stdin");
        let markdown = convert_html_to_markdown(&input, &config);
        print!("{}", markdown);
    }
}

fn process_input(input: &str, output: Option<&String>, overwrite: bool, config: &Config) {
    let path = Path::new(input);

    if path.is_file() {
        let html = fs::read_to_string(path).expect("Failed to read input file");
        let markdown = convert_html_to_markdown(&html, config);

        if let Some(out) = output {
            let out_path = Path::new(out);
            fs::write(out_path, markdown).expect("Failed to write output file");
        } else {
            print!("{}", markdown);
        }
    } else if path.is_dir() || input.contains('*') {
        let output_dir = output.expect("Output must be a directory for directory or glob input");
        let out_dir_path = Path::new(output_dir);

        if !out_dir_path.exists() {
            fs::create_dir_all(out_dir_path).expect("Failed to create output directory");
        }

        let file_paths = if path.is_dir() {
            glob::glob(&format!("{}/**/*.html", input))
                .expect("Failed to read glob pattern")
                .filter_map(|p| p.ok())
                .collect::<Vec<_>>()
        } else {
            glob::glob(input)
                .expect("Failed to read glob pattern")
                .filter_map(|p| p.ok())
                .collect::<Vec<_>>()
        };

        for file_path in file_paths {
            if file_path.is_file() {
                let html = fs::read_to_string(&file_path).expect("Failed to read input file");
                let markdown = convert_html_to_markdown(&html, config);

                let file_name = file_path
                    .file_stem()
                    .and_then(|n| n.to_str())
                    .unwrap_or("output");
                let out_file_path = out_dir_path.join(format!("{}.md", file_name));

                if out_file_path.exists() && !overwrite {
                    continue;
                }

                fs::write(out_file_path, markdown).expect("Failed to write output file");
            }
        }
    }
}

fn convert_html_to_markdown(html: &str, config: &Config) -> String {
    let document = Html::parse_document(html);

    let mut converter = HtmlToMarkdownConverter::new(config);
    converter.convert_element(&document.root_element())
}

struct HtmlToMarkdownConverter<'a> {
    config: &'a Config,
}

impl<'a> HtmlToMarkdownConverter<'a> {
    fn new(config: &'a Config) -> Self {
        HtmlToMarkdownConverter { config }
    }

    fn convert_element(&self, element: &scraper::element_ref::ElementRef) -> String {
        let mut output = String::new();

        for node in element.children() {
            if let Some(el) = scraper::element_ref::ElementRef::wrap(node) {
                let tag_name = el.value().name();

                // Check include/exclude selectors
                if let Some(ref include_sel) = self.config.include_selector {
                    if !include_sel.matches(&el) {
                        // Not in include list, skip
                        continue;
                    }
                }

                if let Some(ref exclude_sel) = self.config.exclude_selector {
                    if exclude_sel.matches(&el) {
                        // In exclude list, skip
                        continue;
                    }
                }

                match tag_name {
                    "p" => output.push_str(&self.handle_paragraph(&el)),
                    "div" => output.push_str(&self.convert_element(&el)),
                    "span" => output.push_str(&self.convert_element(&el)),
                    "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                        output.push_str(&self.handle_heading(tag_name, &el))
                    }
                    "strong" | "b" => output.push_str(&self.handle_strong(&el)),
                    "em" | "i" => output.push_str(&self.handle_em(&el)),
                    "code" => output.push_str(&self.handle_code(&el)),
                    "pre" => output.push_str(&self.handle_pre(&el)),
                    "a" => output.push_str(&self.handle_link(&el)),
                    "img" => output.push_str(&self.handle_image(&el)),
                    "ul" => output.push_str(&self.handle_unordered_list(&el)),
                    "ol" => output.push_str(&self.handle_ordered_list(&el)),
                    "li" => output.push_str(&self.handle_list_item(&el)),
                    "blockquote" => output.push_str(&self.handle_blockquote(&el)),
                    "br" => output.push_str("  \n"),
                    "hr" => output.push_str("* * *"),
                    "table" if self.config.plugin_table => {
                        output.push_str(&self.handle_table(&el))
                    }
                    "s" | "del" if self.config.plugin_strikethrough => {
                        output.push_str(&self.handle_strikethrough(&el))
                    }
                    _ => output.push_str(&self.convert_element(&el)),
                }
            } else if let Some(text_node) = node.value().as_text() {
                let text = text_node.text.trim();
                if !text.is_empty() {
                    output.push_str(&self.escape_markdown(text));
                }
            }
        }

        output.trim_end().to_string()
    }

    fn get_text_content(&self, element: &scraper::element_ref::ElementRef) -> String {
        let mut text = String::new();

        for node in element.children() {
            if let Some(el) = scraper::element_ref::ElementRef::wrap(node) {
                text.push_str(&self.get_text_content(&el));
            } else if let Some(text_node) = node.value().as_text() {
                text.push_str(&text_node.text);
            }
        }

        text
    }

    fn get_inner_html(&self, element: &scraper::element_ref::ElementRef) -> String {
        self.convert_element(element)
    }

    fn handle_paragraph(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.convert_element(element);
        if content.is_empty() {
            String::new()
        } else {
            format!("{}\n\n", content)
        }
    }

    fn handle_heading(
        &self,
        tag_name: &str,
        element: &scraper::element_ref::ElementRef,
    ) -> String {
        let level = tag_name[1..].parse::<usize>().unwrap_or(1);
        let content = self.convert_element(element);
        let hashes = "#".repeat(level);
        format!("{} {}\n\n", hashes, content)
    }

    fn handle_strong(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.convert_element(element);
        format!("{}{}{}", self.config.strong_delimiter, content, self.config.strong_delimiter)
    }

    fn handle_em(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.convert_element(element);
        format!("*{}*", content)
    }

    fn handle_code(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.get_text_content(element);
        format!("`{}`", content)
    }

    fn handle_pre(&self, element: &scraper::element_ref::ElementRef) -> String {
        let mut content = String::new();
        let selector = Selector::parse("code").unwrap();

        if let Some(code_el) = element.select(&selector).next() {
            content = self.get_text_content(&code_el);
        } else {
            content = self.get_text_content(element);
        }

        format!("```\n{}\n```\n\n", content)
    }

    fn handle_link(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.convert_element(element);
        let href = element
            .value()
            .attr("href")
            .unwrap_or("")
            .to_string();
        let href = if let Some(ref domain) = self.config.domain {
            self.resolve_url(domain, &href)
        } else {
            href
        };
        format!("[{}]({})", content, href)
    }

    fn handle_image(&self, element: &scraper::element_ref::ElementRef) -> String {
        let alt = element.value().attr("alt").unwrap_or("").to_string();
        let src = element.value().attr("src").unwrap_or("").to_string();
        let src = if let Some(ref domain) = self.config.domain {
            self.resolve_url(domain, &src)
        } else {
            src
        };
        format!("![{}]({})", alt, src)
    }

    fn handle_unordered_list(&self, element: &scraper::element_ref::ElementRef) -> String {
        let selector = Selector::parse("li").unwrap();
        let mut output = String::new();

        for li in element.select(&selector) {
            let content = self.convert_element(&li).trim().to_string();
            output.push_str(&format!("- {}\n", content));
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn handle_ordered_list(&self, element: &scraper::element_ref::ElementRef) -> String {
        let selector = Selector::parse("li").unwrap();
        let mut output = String::new();
        let mut counter = 1;

        for li in element.select(&selector) {
            let content = self.convert_element(&li).trim().to_string();
            output.push_str(&format!("{}. {}\n", counter, content));
            counter += 1;
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn handle_list_item(&self, element: &scraper::element_ref::ElementRef) -> String {
        self.convert_element(element)
    }

    fn handle_blockquote(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.convert_element(element);
        let lines: Vec<&str> = content.lines().collect();
        let mut output = String::new();

        for line in lines {
            if !line.is_empty() {
                output.push_str(&format!("> {}\n", line));
            } else {
                output.push_str(">\n");
            }
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn handle_strikethrough(&self, element: &scraper::element_ref::ElementRef) -> String {
        let content = self.convert_element(element);
        format!("~~{}~~", content)
    }

    fn handle_table(&self, element: &scraper::element_ref::ElementRef) -> String {
        if element.value().attr("role") == Some("presentation") && !self.config.table_presentation_tables
        {
            return String::new();
        }

        let mut rows = Vec::new();
        let tr_selector = Selector::parse("tr").unwrap();
        let th_selector = Selector::parse("th").unwrap();
        let td_selector = Selector::parse("td").unwrap();

        for tr in element.select(&tr_selector) {
            let mut row = Vec::new();
            let cells: Vec<_> = tr.select(&th_selector).chain(tr.select(&td_selector)).collect();

            for cell in cells {
                let content = self.get_text_content(&cell).trim().to_string();
                row.push(content);
            }

            if !row.is_empty() && (!self.config.table_skip_empty_rows || row.iter().any(|c| !c.is_empty())) {
                rows.push(row);
            }
        }

        if rows.is_empty() {
            return String::new();
        }

        let mut output = String::new();
        let max_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);

        for (row_idx, row) in rows.iter().enumerate() {
            output.push('|');
            for (col_idx, cell) in row.iter().enumerate() {
                let padding = match self.config.table_cell_padding_behavior.as_str() {
                    "minimal" => "",
                    "aligned" | _ => " ",
                };
                output.push_str(&format!("{}{}{}", padding, cell, padding));
                output.push('|');
            }
            // Add empty cells if needed
            for _ in row.len()..max_cols {
                let padding = match self.config.table_cell_padding_behavior.as_str() {
                    "minimal" => "",
                    "aligned" | _ => " ",
                };
                output.push_str(&format!("{}{}{}|", padding, "", padding));
            }
            output.push('\n');

            if row_idx == 0 {
                output.push('|');
                for _ in 0..max_cols {
                    output.push_str("----------|");
                }
                output.push('\n');
            }
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn resolve_url(&self, base: &str, url: &str) -> String {
        if url.starts_with("http://") || url.starts_with("https://") {
            return url.to_string();
        }

        if let Ok(base_url) = Url::parse(base) {
            if let Ok(resolved) = base_url.join(url) {
                return resolved.to_string();
            }
        }

        url.to_string()
    }

    fn escape_markdown(&self, text: &str) -> String {
        let mut result = String::new();
        let chars_to_escape = ['\\', '*', '_', '[', ']', '(', ')', '`', '#', '+', '-', '.', '!', '|', '>'];

        for c in text.chars() {
            if chars_to_escape.contains(&c) {
                result.push('\\');
            }
            result.push(c);
        }

        result
    }
}
