                    config.strong_delimiter = args[i].clone();
                }
            }
            "--plugin-strikethrough" => {
                config.plugin_strikethrough = true;
            }
            "--plugin-table" => {
                config.plugin_table = true;
            }
            "--opt-table-cell-padding-behavior" => {
                i += 1;
                if i < args.len() {
                    config.table_cell_padding_behavior = args[i].clone();
                }
            }
            "--opt-table-header-promotion" => {
                config.table_header_promotion = true;
            }
            "--opt-table-newline-behavior" => {
                i += 1;
                if i < args.len() {
                    config.table_newline_behavior = args[i].clone();
                }
            }
            "--opt-table-presentation-tables" => {
                config.table_presentation_tables = true;
            }
            "--opt-table-skip-empty-rows" => {
                config.table_skip_empty_rows = true;
            }
            "--opt-table-span-cell-behavior" => {
                i += 1;
                if i < args.len() {
                    config.table_span_cell_behavior = args[i].clone();
                }
            }
            _ => {}
        }
        i += 1;
    }

    if show_version {
        println!("html2markdown\n\nGitVersion:  dev\nGitCommit:   none\nBuildDate:   unknown");
        return;
    }

    if show_help {
        print_help();
        return;
    }

    if let Some(input) = input_path {
        process_input(&input, output_path.as_ref(), output_overwrite, &config);
    } else {
        let mut html = String::new();
        io::stdin()
            .read_to_string(&mut html)
            .expect("Failed to read from stdin");
        let markdown = convert_html_to_markdown(&html, &config);
        print!("{}", markdown);
    }
}

