    let mut config = Config::default();
    let mut input_path: Option<String> = None;
    let mut output_path: Option<String> = None;
    let mut output_overwrite = false;
    let mut show_help = false;
    let mut show_version = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        // Handle arguments with = sign (e.g., --opt-strong-delimiter="__")
        if arg.contains('=') {
            let parts: Vec<&str> = arg.splitn(2, '=').collect();
            if parts.len() == 2 {
                let key = parts[0];
                let value = parts[1].to_string();

                match key {
                    "--opt-strong-delimiter" => config.strong_delimiter = value,
                    "--domain" => config.domain = Some(value),
                    "--exclude-selector" => config.exclude_selector = Some(value),
                    "--include-selector" => config.include_selector = Some(value),
                    "--opt-table-cell-padding-behavior" => config.table_cell_padding_behavior = value,
                    "--opt-table-newline-behavior" => config.table_newline_behavior = value,
                    "--opt-table-span-cell-behavior" => config.table_span_cell_behavior = value,
                    "--input" => input_path = Some(value),
                    "--output" => output_path = Some(value),
                    _ => {}
                }
                i += 1;
                continue;
            }
        }

        match arg.as_str() {
            "-v" | "--version" => {
                show_version = true;
            }
            "--help" => {
                show_help = true;
            }
            "--input" => {
                i += 1;
                if i < args.len() {
                    input_path = Some(args[i].clone());
                }
            }
            "--output" => {
                i += 1;
                if i < args.len() {
                    output_path = Some(args[i].clone());
                }
            }
            "--output-overwrite" => {
                output_overwrite = true;
            }
            "--domain" => {
                i += 1;
                if i < args.len() {
                    config.domain = Some(args[i].clone());
                }
            }
            "--exclude-selector" => {
                i += 1;
                if i < args.len() {
                    config.exclude_selector = Some(args[i].clone());
                }
            }
            "--include-selector" => {
                i += 1;
                if i < args.len() {
                    config.include_selector = Some(args[i].clone());
                }
            }
            "--opt-strong-delimiter" => {
                i += 1;
                if i < args.len() {
                    config.strong_delimiter = args[i].clone();
                }
            }
            "--plugin-strikethrough" => {
                config.plugin_strikethrough = true;
            }
            "--plugin-table" => {
                config.plugin_table = true;
            }
            "--opt-table-cell-padding-behavior" => {
                i += 1;
                if i < args.len() {
                    config.table_cell_padding_behavior = args[i].clone();
                }
            }
            "--opt-table-header-promotion" => {
                config.table_header_promotion = true;
            }
            "--opt-table-newline-behavior" => {
                i += 1;
                if i < args.len() {
                    config.table_newline_behavior = args[i].clone();
                }
            }
            "--opt-table-presentation-tables" => {
                config.table_presentation_tables = true;
            }
            "--opt-table-skip-empty-rows" => {
                config.table_skip_empty_rows = true;
            }
            "--opt-table-span-cell-behavior" => {
                i += 1;
                if i < args.len() {
                    config.table_span_cell_behavior = args[i].clone();
                }
            }
            _ => {}
        }
        i += 1;
    }

    if show_version {
        println!("html2markdown\n\nGitVersion:  dev\nGitCommit:   none\nBuildDate:   unknown");
        return;
    }

    if show_help {
        print_help();
        return;
    }

    if let Some(input) = input_path {
        process_input(&input, output_path.as_ref(), output_overwrite, &config);
    } else {
        let mut html = String::new();
        io::stdin()
            .read_to_string(&mut html)
            .expect("Failed to read from stdin");
        let markdown = convert_html_to_markdown(&html, &config);
        print!("{}", markdown);
    }
}

fn print_help() {
    println!(
        r#"
# html2markdown - convert html to markdown [version dev]

Convert HTML to Markdown. Even works with entire websites!

## Basics

By default the "Commonmark" Plugin will be enabled. You can customize the options,
for example changing the appearance of bold with --opt-strong-delimiter="__"

Other Plugins can also be enabled. For example "GitHub Flavored Markdown" (GFM)
extends Commonmark with more features.

## Relative / Absolute Links

Use --domain="https://example.com" to convert *relative* links to *absolute* links.
The same also works for images.

## Escaping

Some characters have a special meaning in markdown. The library escapes these — if necessary.
See the documentation for more info.

## Security

Once you convert this markdown *back* to HTML you need to be careful of malicious content. 
Use a HTML sanitizer before displaying the HTML in the browser!


## Examples

    echo "<strong>important</strong>" | html2markdown

    curl --no-progress-meter http://example.com | html2markdown


    html2markdown --input file.html --output file.md

    html2markdown --input "src/*.html" --output "dist/"


## Flags

    -v, --version
        show the version of html2markdown and exit

    --help

