        Config {
            strong_delimiter: "**".to_string(),
            plugin_strikethrough: false,
            plugin_table: false,
            domain: None,
            include_selector: None,
            exclude_selector: None,
            table_cell_padding_behavior: "aligned".to_string(),
            table_header_promotion: false,
            table_newline_behavior: "preserve".to_string(),
            table_presentation_tables: false,
