fn process_input(input: &str, output: Option<&String>, _overwrite: bool, config: &Config) {
    let path = Path::new(input);

    if path.is_file() {
        let html = fs::read_to_string(path).expect("Failed to read input file");
        let markdown = convert_html_to_markdown(&html, config);

        if let Some(out) = output {
            let out_path = Path::new(out);
            fs::write(out_path, markdown).expect("Failed to write output file");
        } else {
            print!("{}", markdown);
        }
    } else if path.is_dir() {
        // For directories, recursively process HTML files
        let output_dir = output.expect("Output must be a directory for directory input");
        let out_dir_path = Path::new(output_dir);

        if !out_dir_path.exists() {
            fs::create_dir_all(out_dir_path).expect("Failed to create output directory");
        }

        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let file_path = entry.path();
                if file_path.is_file() && file_path.extension().map_or(false, |ext| ext == "html") {
                    let html = fs::read_to_string(&file_path).expect("Failed to read input file");
                    let markdown = convert_html_to_markdown(&html, config);

                    let file_name = file_path
                        .file_stem()
                        .and_then(|n| n.to_str())
                        .unwrap_or("output");
                    let out_file_path = out_dir_path.join(format!("{}.md", file_name));

                    fs::write(out_file_path, markdown).expect("Failed to write output file");
                }
            }
        }
    }
}

fn convert_html_to_markdown(html: &str, config: &Config) -> String {
    let parser = HtmlParser::new(html);
    let nodes = parser.parse();
    let converter = HtmlToMarkdownConverter::new(config.clone());
    converter.convert_nodes(&nodes)
}

#[derive(Debug, Clone)]
enum HtmlNode {
    Text(String),
    Element {
        tag: String,
        attrs: HashMap<String, String>,
        children: Vec<HtmlNode>,
    },
}

struct HtmlParser {
    html: String,
    pos: usize,
}

impl HtmlParser {
    fn new(html: &str) -> Self {
        HtmlParser {
            html: html.to_string(),
            pos: 0,
        }
    }

    fn parse(&self) -> Vec<HtmlNode> {
        let mut parser = HtmlParser {
            html: self.html.clone(),
            pos: 0,
        };
        parser.parse_nodes()
    }

    fn parse_nodes(&mut self) -> Vec<HtmlNode> {
        let mut nodes = Vec::new();

        while self.pos < self.html.len() {
            // Skip whitespace
            while self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap().is_whitespace() {
                self.pos += 1;
            }

            if self.pos >= self.html.len() {
                break;
            }

            if self.peek_char() == Some('<') {
                if self.peek_str(2) == Some("</".to_string()) {
                    // End tag, stop parsing
                    break;
                } else if self.peek_str(4) == Some("<!--".to_string()) {
                    // Comment, skip it
                    self.skip_comment();
                } else if self.peek_str(2) == Some("<!".to_string()) {
                    // DOCTYPE or other declaration, skip it
                    self.skip_declaration();
                } else if self.peek_str(2) == Some("<?".to_string()) {
                    // Processing instruction, skip it
                    self.skip_processing_instruction();
                } else {
                    // Start tag
                    if let Some(node) = self.parse_element() {
                        nodes.push(node);
                    }
                }
            } else {
                // Text node
                if let Some(text) = self.parse_text() {
                    if !text.trim().is_empty() {
                        nodes.push(HtmlNode::Text(text));
                    }
                }
            }
        }

        nodes
    }

    fn parse_element(&mut self) -> Option<HtmlNode> {
        if self.peek_char() != Some('<') {
            return None;
        }

        self.pos += 1; // Skip '<'

        // Parse tag name
        let tag_name = self.parse_identifier();
        if tag_name.is_empty() {
            return None;
        }

        // Parse attributes
        let attrs = self.parse_attributes();

        // Check for self-closing
        let is_self_closing = if self.peek_str(2) == Some("/>".to_string()) {
            self.pos += 2;
            true
        } else if self.peek_char() == Some('>') {
            self.pos += 1;
            false
        } else {
            return None;
        };

        let void_elements = ["br", "hr", "img", "input", "meta", "link", "area", "base", "col", "embed", "source", "track", "wbr"];

        if is_self_closing || void_elements.contains(&tag_name.as_str()) {
            return Some(HtmlNode::Element {
                tag: tag_name,
                attrs,
                children: Vec::new(),
            });
        }

        // Parse children
        let children = self.parse_until_end_tag(&tag_name);

        // Parse end tag
        if self.peek_str(2) == Some("</".to_string()) {
            self.pos += 2;
            self.skip_identifier();
            if self.peek_char() == Some('>') {
                self.pos += 1;
            }
        }

        Some(HtmlNode::Element {
            tag: tag_name,
            attrs,
            children,
        })
    }

    fn parse_until_end_tag(&mut self, tag_name: &str) -> Vec<HtmlNode> {
        let mut nodes = Vec::new();

        while self.pos < self.html.len() {
            // Look for end tag
            if self.peek_str(2) == Some("</".to_string()) {
                let end_tag = self.peek_end_tag();
                if end_tag == tag_name {
                    break;
                }
            }

            // Skip whitespace in some cases
            let start_pos = self.pos;
            while self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap().is_whitespace() {
                self.pos += 1;
            }

            if self.pos >= self.html.len() {
                break;
            }

            if self.peek_str(2) == Some("</".to_string()) {
                let end_tag = self.peek_end_tag();
                if end_tag == tag_name {
                    break;
                } else {
                    self.pos = start_pos;
                }
            }

            if self.peek_char() == Some('<') {
                if self.peek_str(4) == Some("<!--".to_string()) {
                    self.skip_comment();
                } else if self.peek_str(2) == Some("<!".to_string()) {
                    self.skip_declaration();
                } else if let Some(node) = self.parse_element() {
                    nodes.push(node);
                } else {
                    self.pos += 1;
                }
            } else {
                // Try to parse text
                self.pos = start_pos;
                if let Some(text) = self.parse_text() {
                    if !text.is_empty() {
                        nodes.push(HtmlNode::Text(text));
                    }
                }
            }
        }

        nodes
    }

    fn parse_text(&mut self) -> Option<String> {
        let start = self.pos;

        while self.pos < self.html.len() && self.peek_char() != Some('<') {
            self.pos += 1;
        }

        if self.pos > start {
            Some(self.html[start..self.pos].to_string())
        } else {
            None
        }
    }

    fn parse_identifier(&mut self) -> String {
        let start = self.pos;

        while self.pos < self.html.len() {
            let c = self.html.chars().nth(self.pos).unwrap();
            if c.is_alphanumeric() || c == '-' || c == ':' {
                self.pos += 1;
            } else {
                break;
            }
        }

        self.html[start..self.pos].to_lowercase()
    }

    fn skip_identifier(&mut self) {
        while self.pos < self.html.len() {
            let c = self.html.chars().nth(self.pos).unwrap();
            if c.is_alphanumeric() || c == '-' || c == ':' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_attributes(&mut self) -> HashMap<String, String> {
        let mut attrs = HashMap::new();

        loop {
            // Skip whitespace
            while self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap().is_whitespace() {
                self.pos += 1;
            }

            if self.pos >= self.html.len() {
                break;
            }

            let c = self.html.chars().nth(self.pos).unwrap();
            if c == '>' || c == '/' {
                break;
            }

            let attr_name = self.parse_identifier();
            if attr_name.is_empty() {
                self.pos += 1;
                continue;
            }

            // Skip whitespace after name
            while self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap().is_whitespace() {
                self.pos += 1;
            }

            let mut attr_value = String::new();
            if self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap() == '=' {
                self.pos += 1;

                // Skip whitespace after =
                while self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap().is_whitespace() {
                    self.pos += 1;
                }

                if self.pos < self.html.len() {
                    let quote = self.html.chars().nth(self.pos).unwrap();
                    if quote == '"' || quote == '\'' {
                        self.pos += 1;
                        let start = self.pos;
                        while self.pos < self.html.len() && self.html.chars().nth(self.pos).unwrap() != quote {
                            self.pos += 1;
                        }
                        attr_value = self.html[start..self.pos].to_string();
                        if self.pos < self.html.len() {
                            self.pos += 1; // Skip closing quote
                        }
                    }
                }
            }

            attrs.insert(attr_name, attr_value);
        }

        attrs
    }

    fn peek_char(&self) -> Option<char> {
        self.html.chars().nth(self.pos)
    }

    fn peek_str(&self, len: usize) -> Option<String> {
        if self.pos + len <= self.html.len() {
            Some(self.html[self.pos..self.pos + len].to_string())
        } else {
            None
        }
    }

    fn peek_end_tag(&self) -> String {
        let start = self.pos + 2; // Skip "</
        let mut end = start;
        while end < self.html.len() {
            let c = self.html.chars().nth(end).unwrap();
            if c == '>' || c.is_whitespace() {
                break;
            }
            end += 1;
        }
        self.html[start..end].to_lowercase()
    }

    fn skip_comment(&mut self) {
        self.pos += 4; // Skip <!--
        while self.pos < self.html.len() {
            if self.peek_str(3) == Some("-->".to_string()) {
                self.pos += 3;
                break;
            }
            self.pos += 1;
        }
    }

    fn skip_declaration(&mut self) {
        self.pos += 1; // Skip '<'
        while self.pos < self.html.len() && self.peek_char() != Some('>') {
            self.pos += 1;
        }
        if self.peek_char() == Some('>') {
            self.pos += 1;
        }
    }

    fn skip_processing_instruction(&mut self) {
        self.pos += 2; // Skip '<?'
        while self.pos < self.html.len() {
            if self.peek_str(2) == Some("?>".to_string()) {
                self.pos += 2;
                break;
            }
            self.pos += 1;
        }
    }
}

struct HtmlToMarkdownConverter {
    config: Config,
}

impl HtmlToMarkdownConverter {
    fn new(config: Config) -> Self {
        HtmlToMarkdownConverter { config }
    }

    fn convert_nodes(&self, nodes: &[HtmlNode]) -> String {
        nodes
            .iter()
            .map(|node| self.convert_node(node))
            .collect::<Vec<_>>()
            .join("")
    }

    fn convert_node(&self, node: &HtmlNode) -> String {
        match node {
            HtmlNode::Text(text) => self.escape_markdown(text),
            HtmlNode::Element { tag, attrs, children } => {
                self.handle_element(tag, attrs, children)
            }
        }
    }

    fn handle_element(&self, tag: &str, attrs: &HashMap<String, String>, children: &[HtmlNode]) -> String {
        match tag {
            "p" => {
                let content = self.convert_nodes(children);
                if content.trim().is_empty() {
                    String::new()
                } else {
                    format!("{}\n\n", content)
                }
            }
            "div" | "span" => self.convert_nodes(children),
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                let level = tag[1..].parse::<usize>().unwrap_or(1);
                let content = self.convert_nodes(children);
                let hashes = "#".repeat(level);
                format!("{} {}\n\n", hashes, content)
            }
            "strong" | "b" => {
                let content = self.convert_nodes(children);
                format!("{}{}{}", self.config.strong_delimiter, content, self.config.strong_delimiter)
            }
            "em" | "i" => {
                let content = self.convert_nodes(children);
                format!("*{}*", content)
            }
            "code" => {
                let content = self.get_text_content(children);
                format!("`{}`", content)
            }
            "pre" => {
                let mut content = self.get_text_content(children);
                // If pre has a code child, use that
                for child in children {
                    if let HtmlNode::Element { tag: child_tag, children: child_children, .. } = child {
                        if child_tag == "code" {
                            content = self.get_text_content(child_children);
                            break;
                        }
                    }
                }
                format!("```\n{}\n```\n\n", content)
            }
            "a" => {
                let content = self.convert_nodes(children);
                let href = attrs.get("href").cloned().unwrap_or_default();
                let href = if let Some(ref domain) = self.config.domain {
                    self.resolve_url(domain, &href)
                } else {
                    href
                };
                format!("[{}]({})", content, href)
            }
            "img" => {
                let alt = attrs.get("alt").cloned().unwrap_or_default();
                let src = attrs.get("src").cloned().unwrap_or_default();
                let src = if let Some(ref domain) = self.config.domain {
                    self.resolve_url(domain, &src)
                } else {
                    src
                };
                format!("![{}]({})", alt, src)
            }
            "ul" => self.handle_unordered_list(children),
            "ol" => self.handle_ordered_list(children),
            "li" => self.convert_nodes(children),
            "blockquote" => self.handle_blockquote(children),
            "br" => "  \n".to_string(),
            "hr" => "* * *".to_string(),
            "table" if self.config.plugin_table => {
                self.handle_table(attrs, children)
            }
            "s" | "del" if self.config.plugin_strikethrough => {
                let content = self.convert_nodes(children);
                format!("~~{}~~", content)
            }
            _ => self.convert_nodes(children),
        }
    }

    fn get_text_content(&self, nodes: &[HtmlNode]) -> String {
        nodes
            .iter()
            .map(|node| match node {
                HtmlNode::Text(text) => text.clone(),
                HtmlNode::Element { children, .. } => self.get_text_content(children),
            })
            .collect::<Vec<_>>()
            .join("")
    }

    fn handle_unordered_list(&self, children: &[HtmlNode]) -> String {
        let mut output = String::new();

        for child in children {
            if let HtmlNode::Element { tag, children: li_children, .. } = child {
                if tag == "li" {
                    let content = self.convert_nodes(li_children).trim().to_string();
                    output.push_str(&format!("- {}\n", content));
                }
            }
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn handle_ordered_list(&self, children: &[HtmlNode]) -> String {
        let mut output = String::new();
        let mut counter = 1;

        for child in children {
            if let HtmlNode::Element { tag, children: li_children, .. } = child {
                if tag == "li" {
                    let content = self.convert_nodes(li_children).trim().to_string();
                    output.push_str(&format!("{}. {}\n", counter, content));
                    counter += 1;
                }
            }
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn handle_blockquote(&self, children: &[HtmlNode]) -> String {
        let content = self.convert_nodes(children);
        let lines: Vec<&str> = content.lines().collect();
        let mut output = String::new();

        for line in lines {
            if !line.is_empty() {
                output.push_str(&format!("> {}\n", line));
            } else {
                output.push_str(">\n");
            }
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn handle_table(&self, attrs: &HashMap<String, String>, children: &[HtmlNode]) -> String {
        if attrs.get("role").map_or(false, |r| r == "presentation") && !self.config.table_presentation_tables
        {
            return String::new();
        }

        let mut rows = Vec::new();

        for child in children {
            if let HtmlNode::Element { tag, children: row_children, .. } = child {
                if tag == "tr" {
                    let mut row = Vec::new();
                    for cell in row_children {
                        if let HtmlNode::Element { tag: cell_tag, children: cell_children, .. } = cell {
                            if cell_tag == "th" || cell_tag == "td" {
                                let content = self.get_text_content(cell_children).trim().to_string();
                                row.push(content);
                            }
                        }
                    }
                    if !row.is_empty() && (!self.config.table_skip_empty_rows || row.iter().any(|c| !c.is_empty())) {
                        rows.push(row);
                    }
                }
            }
        }

        if rows.is_empty() {
            return String::new();
        }

        let mut output = String::new();
        let max_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);

        for (row_idx, row) in rows.iter().enumerate() {
            output.push('|');
            for (_, cell) in row.iter().enumerate() {
                let padding = match self.config.table_cell_padding_behavior.as_str() {
                    "minimal" => "",
                    "aligned" | _ => " ",
                };
                output.push_str(&format!("{}{}{}", padding, cell, padding));
                output.push('|');
            }
            // Add empty cells if needed
            for _ in row.len()..max_cols {
                let padding = match self.config.table_cell_padding_behavior.as_str() {
                    "minimal" => "",
                    "aligned" | _ => " ",
                };
                output.push_str(&format!("{}{}{}|", padding, "", padding));
            }
            output.push('\n');

            if row_idx == 0 {
                output.push('|');
                for _ in 0..max_cols {
                    output.push_str("----------|");
                }
                output.push('\n');
            }
        }

        if !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn resolve_url(&self, base: &str, url: &str) -> String {
        if url.starts_with("http://") || url.starts_with("https://") {
            return url.to_string();
        }

        if url.starts_with("//") {
            return format!("https:{}", url);
        }

        if url.starts_with('/') {
            // Absolute path - extract domain from base
            let base_without_proto = if let Some(idx) = base.find("://") {
                &base[idx + 3..]
            } else {
                base
            };

            if let Some(slash_idx) = base_without_proto.find('/') {
                let domain = &base_without_proto[..slash_idx];
                if let Some(proto_idx) = base.find("://") {
                    let proto = &base[..proto_idx + 3];
                    return format!("{}{}{}", proto, domain, url);
                }
            } else {
                // No path in base URL
                return format!("{}{}", base, url);
            }
        }

        // Relative URL - combine with base
        if let Some(last_slash) = base.rfind('/') {
            format!("{}/{}", &base[..last_slash], url)
        } else {
            format!("{}/{}", base, url)
        }
    }

    fn escape_markdown(&self, text: &str) -> String {
        let mut result = String::new();
        // Only escape characters that could have special meaning in markdown
        let chars_to_escape = ['\\', '*', '_', '[', ']', '(', ')', '`', '#', '+', '-', '!', '|', '>'];

        for c in text.chars() {
            if chars_to_escape.contains(&c) {
                result.push('\\');
            }
            result.push(c);
        }

        result
    }
}
